const GROUP_NAMES = 'ABCDEFGHIJKLMNOP';

// Fisher-Yates with crypto randomness when available.
function shuffle(a, rnd = Math.random) { a = [...a]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

// Round robin (circle method). Returns rounds of [home, away] pairs; odd counts get a rest each round.
function roundRobin(teams) {
  const t = [...teams]; if (t.length % 2) t.push(null);
  const n = t.length, rounds = [];
  for (let r = 0; r < n - 1; r++) {
    const pairs = [];
    for (let i = 0; i < n / 2; i++) {
      const a = t[i], b = t[n - 1 - i];
      if (a !== null && b !== null) pairs.push(r % 2 && i === 0 ? [b, a] : [a, b]);
    }
    rounds.push(pairs);
    t.splice(1, 0, t.pop()); // rotate everyone but the first
  }
  return rounds;
}

// Standard bracket order so top seeds meet as late as possible: size 4 -> [1,4,2,3].
function bracketOrder(size) { let o = [1]; while (o.length < size) { const s = o.length * 2; o = o.flatMap(x => [x, s + 1 - x]); } return o; }
const roundLabel = (size, i, count) => size === 2 ? 'Final' : size === 4 ? `Semi-final ${i}` : size === 8 ? `Quarter-final ${i}` : `Round of ${size} · ${i}`;

// seeds: [{entry} | {ref}] best first. Byes go to the top seeds. Returns matches with refs to earlier winners.
function knockout(seeds, firstNo) {
  const out = []; let size = 1; while (size < seeds.length) size *= 2;
  let slots = bracketOrder(size).map(s => seeds[s - 1] || null), no = firstNo, round = 1;
  while (slots.length > 1) {
    const next = [], pairs = slots.length / 2; let i = 0;
    for (let k = 0; k < slots.length; k += 2) {
      const a = slots[k], b = slots[k + 1];
      if (a && b) { i++; out.push({ stage: 'KNOCKOUT', round_no: round, label: roundLabel(slots.length, i, pairs), home: a, away: b, match_no: no }); next.push({ ref: `W#${no}` }); no++; }
      else next.push(a || b || null);
    }
    slots = next; round++;
  }
  return out;
}

/**
 * Builds one division's matches.
 * d: { id, name, format, group_count, qualify_per_group }, entries: [entry ids], o: { draw, groups: {entryId: groupNo}, seeds: [entryIds] }
 * Returns { error } or { groups: {entryId: groupNo}, seeds: {entryId: seed}, matches: [...] } (matches without times).
 */
function buildDivision(d, entries, o, rnd) {
  const n = entries.length;
  if (n < 2) return { error: `${d.name} needs at least 2 confirmed teams.` };
  const manual = o.draw === 'MANUAL';
  if (d.format === 'KNOCKOUT') {
    let order;
    if (manual) {
      order = (o.seeds || []).map(Number);
      if (order.length !== n || new Set(order).size !== n || order.some(id => !entries.includes(id))) return { error: `${d.name}: put every confirmed team in the seeding order.` };
    } else order = shuffle(entries, rnd);
    const seeds = Object.fromEntries(order.map((id, i) => [id, i + 1]));
    return { groups: {}, seeds, matches: knockout(order.map(id => ({ entry: id })), 1) };
  }
  // Groups: LEAGUE = one group; LEAGUE_KNOCKOUT = the division's group count (at least 2 teams per group).
  const g = d.format === 'LEAGUE' ? 1 : Math.max(1, Math.min(Number(d.group_count) || 1, Math.floor(n / 2)));
  let groups = {};
  if (manual && g > 1) {
    for (const id of entries) { const v = Number((o.groups || {})[id]); if (!(v >= 1 && v <= g)) return { error: `${d.name}: put every confirmed team in a group.` }; groups[id] = v; }
    for (let k = 1; k <= g; k++) if (Object.values(groups).filter(v => v === k).length < 2) return { error: `${d.name}: Group ${GROUP_NAMES[k - 1]} needs at least 2 teams.` };
  } else {
    // Deal shuffled teams into groups in turn so sizes differ by at most one.
    (g > 1 ? shuffle(entries, rnd) : (manual ? entries : shuffle(entries, rnd))).forEach((id, i) => { groups[id] = (i % g) + 1; });
  }
  const members = k => entries.filter(id => groups[id] === k).sort((a, b) => entries.indexOf(a) - entries.indexOf(b));
  const perGroup = Array.from({ length: g }, (_, k) => roundRobin(members(k + 1)));
  const maxRounds = Math.max(...perGroup.map(r => r.length));
  const matches = []; let no = 1;
  for (let r = 0; r < maxRounds; r++)
    for (let k = 0; k < g; k++)
      for (const [h, a] of perGroup[k][r] || []) matches.push({ stage: 'GROUP', group_no: k + 1, round_no: r + 1, label: null, home: { entry: h }, away: { entry: a }, match_no: no++ });
  if (d.format === 'LEAGUE_KNOCKOUT') {
    const smallest = Math.min(...Array.from({ length: g }, (_, k) => members(k + 1).length));
    const q = Math.max(1, Math.min(Number(d.qualify_per_group) || 1, smallest - (g === 1 ? 0 : 0)));
    const seeds = [];
    for (let pos = 1; pos <= q; pos++) for (let k = 1; k <= g; k++) seeds.push({ ref: `G${k}#${pos}` });
    if (seeds.length >= 2) matches.push(...knockout(seeds, no));
  }
  return { groups, seeds: {}, matches };
}

/**
 * Gives every match a time and pitch. Matches run in order; a slot holds up to `pitches` matches, a team never plays
 * twice in a slot, and each knockout round starts in a fresh slot after the previous stage. Slots that would end after
 * dayEnd move to the next day at dayStart. Returns { error } or { end } (minute after the last slot).
 */
function schedule(matches, startMin, o) {
  const { pitches, gap, dayStart, dayEnd, lastDay } = o;
  let t = startMin, used = [], busy = new Set(), lastKey = null;
  const fit = () => {
    const day = Math.floor(t / 1440) * 1440;
    if (t - day < dayStart) t = day + dayStart;
    if (t - day + gap > dayEnd) t = day + 1440 + dayStart;
    return Math.floor(t / 1440) * 1440 <= lastDay;
  };
  const newSlot = () => { t += gap; used = []; busy = new Set(); };
  if (!fit()) return { error: 'starts after the last day of the tournament' };
  for (const m of matches) {
    const key = m.stage === 'KNOCKOUT' ? `K${m.round_no}` : 'G';
    const sides = [m.home, m.away].map(s => s.entry ? `e${s.entry}` : s.ref);
    const refsEarlier = sides.some(s => s.startsWith('W#') && busy.has(s));
    if (used.length && (used.length >= pitches || key !== lastKey || sides.some(s => busy.has(s)) || refsEarlier)) {
      newSlot();
      if (!fit()) return { error: 'does not fit before the last day ends' };
    }
    m.pitch = used.length + 1; m.at = fromMin(t);
    used.push(m.match_no); sides.forEach(s => busy.add(s)); busy.add(`W#${m.match_no}`); lastKey = key;
  }
  return { end: t + gap };
}


const s = $in, r = $('Check Request').first().json;
const fail = (st, m) => [{ json: { ok: false, status: st, body: { success: false, message: m } } }];
if (!s.tid) return fail(404, 'Tournament not found.');
if (Number(s.is_owner) !== 1) return fail(403, 'Only the organiser can make fixtures.');
