  const entries = (x.d.entries || []).map(Number);
  const built = buildDivision(x.d, entries, x, rnd);
  if (built.error) return fail(422, built.error);
  const start = x.start ? toMin(x.start) : cursor;
  if (x.start && (start < toMin(s.start_date + ' 00:00') || start >= lastDay + 1440)) return fail(422, `${x.d.name} must start between the tournament's first and last day.`);
