  for (const id of entries) stmts.push(`UPDATE tournament_entries SET group_no = ${add(built.groups[id] ?? null)}, seed = ${add(built.seeds[id] ?? null)} WHERE id = ${add(id)}`);
  stmts.push(`UPDATE tournament_divisions SET fixture_start = ${add(x.start ? fromMin(start) : null)}, fixture_pitches = ${add(x.pitches)}, fixture_gap_minutes = ${add(x.gap)}, fixture_draw = ${add(x.draw)} WHERE id = ${add(x.id)}`);
  for (const m of built.matches)
    rows.push(`(${add(s.tid)}, ${add(x.id)}, ${add(m.match_no)}, ${add(m.stage)}, ${add(m.group_no ?? null)}, ${add(m.round_no)}, ${add(m.label)}, ` +
      `${add(m.home.entry ?? null)}, ${add(m.away.entry ?? null)}, ${add(m.home.ref ?? null)}, ${add(m.away.ref ?? null)}, ${add(m.pitch)}, ${add(m.at)})`);
  summary.push({ division_id: x.id, name: x.d.name, matches: built.matches.length, first: built.matches[0]?.at, last: built.matches[built.matches.length - 1]?.at });
}
